// (v247) сейв — решение команды: личные размены и пики отменяются, в дуэли никто не выходит
function saveCancelTrades(team){
  bots.forEach(function(b){ if(b.team !== team || !b.alive) return;
    b._tradeLock = null; b._fillLock = null; b._tradeUntil = 0; b._waitPopUntil = 0;
    if(b.post && b.post.tag === "tradeR") clearPost(b); });
}
function teamSaving(team){ var t = team === "CT" ? teamTac.CT : teamTac.T; return !!(t && t.saving); }
function cl0save(){ return teamTac.CT && teamTac.CT.saving; }
// ======================= РАЗДЕЛ 9: подача матча =======================

var clutchShown = null, clutchInfo = null;
function esc(t){ return String(t).replace(/[&<>]/g, function(c){ return {"&":"&amp;","<":"&lt;",">":"&gt;"}[c]; }); }
// (v241) киллфид как в CS2 (из переделки): иконка оружия, ассист (40+ урона или флешка), значки
// «в голову», «убийца ослеплён». wkey — ключ WEAPONS, "HE", "MOLOTOV" или "KNIFE"
function killAssist(att, vic){
  var best = null, bd = 39, D = vic._dmgBy || {};
  for(var id in D) if((!att || id !== att.id) && D[id] > bd){ bd = D[id]; best = id; }
  if(best) return {id:best, flash:false};
  if(vic._blindBy && vic.blindUntil > tick && (!att || vic._blindBy !== att.id)) return {id:vic._blindBy, flash:true};
  return null;
}
function feedKill(att, vic, wkey, hs, mods){
  mods = mods || {};
  teamDeath(att, vic);   // до киллфида в знании: видел убийцу — успевает сказать, откуда
  knowKill(att, vic);
  var as = killAssist(att, vic);
  killfeed.unshift({kind:"kill", att:att?nick(att.id):"?", attTeam:att?att.team:"", as:as?nick(as.id):null, asFlash:as&&as.flash,
    vic:nick(vic.id), vicTeam:vic.team, w:wkey, hs:hs, smoke:!!mods.smoke, wall:!!mods.wall, noscope:!!mods.noscope, blind:!!mods.blind, tk:!!mods.tk, t:nowTs, at:simTime});
  if(killfeed.length > 8) killfeed.length = 8;
  renderFeed();
  // мультикилл-баннер
  if(att && att.team !== vic.team && att.roundKills >= 2){
    var lbl = ["", "", "2K", "3K", "4K", "ACE"][Math.min(5, att.roundKills)];
    showBanner((att.roundKills >= 5 ? "ACE — " : lbl+" — ")+nick(att.id), att.team, 2200);
  }
  checkClutch();
}
