// (v397, М145) Dual Berettas — в наборе владельца иконки нет: два его силуэта P250 со сдвигом (как иконка «элиток» в CS2), задний
// приглушён. Без иконки панель игрока не показывала оружие вовсе — выглядело как «нет пистолета» (CT берут их в 24 % пистолеток),
// а в киллфиде убийство было без оружия
KF_ICON.ELITE = (function(p){ var dx = 12, dy = 6, g = p.svg.replace(/ id="[^"]*"/g, "");
  return {vb: "0 0 "+(p.w+dx)+" "+(p.h+dy), w: p.w+dx, h: p.h+dy, svg: '<g opacity="0.6">'+g+'</g><g transform="translate('+dx+' '+dy+')">'+g+'</g>'}; })(KF_ICON.P250);
// (v288) иконка бомбы — своя (в наборе владельца её нет), в том же стиле: белый силуэт C4 — корпус, табло, провода
KF_ICON.C4 = {vb:"0 0 40 32", w:40, h:32, svg:'<g fill="#FFFFFF"><rect x="3" y="9" width="30" height="18" rx="2"/><rect x="33" y="12" width="4" height="12" rx="1" opacity="0.8"/></g>'+
  '<rect x="7" y="12" width="13" height="6" rx="1" fill="#1b1f17"/><g fill="#1b1f17"><rect x="23" y="12" width="3" height="3"/><rect x="27.5" y="12" width="3" height="3"/><rect x="23" y="16.5" width="3" height="3"/><rect x="27.5" y="16.5" width="3" height="3"/><rect x="7" y="21" width="23" height="2.5"/></g>'+
  '<path d="M8 9 C8 4 14 4 15 8 M18 9 C18 3 25 3 26 8" stroke="#FFFFFF" stroke-width="1.8" fill="none"/>'};
var KF_MOD_T = {smoke:"через смок", wall:"прострел", hs:"в голову", noscope:"без прицела", blind:"убийца ослеплён", flash:"ассист флешкой"};
// (v288) иконка киллфида как картинка для радара (кэш)
var KF_IMG = {};
function kfImg(key){
  if(KF_IMG[key]) return KF_IMG[key]; var ic = KF_ICON[key]; if(!ic || typeof Image === "undefined") return null;
  var im = new Image(); im.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+ic.vb+'">'+ic.svg+'</svg>');
  return (KF_IMG[key] = im);
}
