var NADE_ICON_FILL = {flash:"#ffffff", he:"#ff7a6c", molly:"#ffa24a", inc:"#ffa24a", smoke:"#dfe3da"}, NADE_IMG = {};
function nadeImg(type, team){
  var k = type === "molly" && team === "CT" ? "inc" : type; if(NADE_IMG[k] !== undefined) return NADE_IMG[k];
  var ic = NADE_ICON[k]; if(!ic || typeof Image === "undefined") return (NADE_IMG[k] = null);
  var im = new Image(); im.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" viewBox="'+ic.vb+'" fill="'+NADE_ICON_FILL[k]+'">'+ic.svg+'</svg>');
  im._ar = ic.w/ic.h; return (NADE_IMG[k] = im);
}
function kfSvg(key, cls, title){
  var ic = KF_ICON[key]; if(!ic) return null;
  var hpx = cls === "wp" ? 16 : 15, wpx = (ic.w*hpx/ic.h).toFixed(1);
  return '<svg class="'+cls+'" viewBox="'+ic.vb+'" width="'+wpx+'" height="'+hpx+'" aria-label="'+title+'"><title>'+title+'</title>'+ic.svg+'</svg>';
}
// (v288) смерть от взрыва бомбы — строка киллфида без убийцы (как в CS2): иконка C4 и жертва. Только показ —
// знание и войс бомбовой смерти идут как раньше (feedKill не зовётся)
function feedBombKill(vic){
  killfeed.unshift({kind:"kill", att:null, attTeam:"", as:null, vic:nick(vic.id), vicTeam:vic.team, w:"C4", t:nowTs, at:simTime});
  if(killfeed.length > 8) killfeed.length = 8;
  renderFeed();
}
function feedEvent(kind, text){
  killfeed.unshift({kind:kind, text:nickify(text), t:nowTs, at:simTime});
  if(killfeed.length > 8) killfeed.length = 8;
  renderFeed();
}
// (v430) строка, которую ещё не показывали, въезжает справа (класс in); уже показанные при перестройке стоят на месте
var HUD_KF_SHOWN = typeof WeakSet !== "undefined" ? new WeakSet() : null;
function kfIn(k){ if(!HUD_KF_SHOWN || HUD_KF_SHOWN.has(k)) return ""; HUD_KF_SHOWN.add(k); return " in"; }
// (v437, владелец 27.10) строка киллфида гаснет через KF_LIFE с игрового времени (пауза — стоит), последние KF_FADE с — затухает.
// Только показ: массив killfeed и знание ботов не трогаются. 8 с — проектное число
var KF_LIFE = 8, KF_FADE = 0.6;
function kfStage(k){ var a = simTime - (k.at != null ? k.at : simTime); return a >= KF_LIFE ? 2 : a >= KF_LIFE - KF_FADE ? 1 : 0; }
// раз в кадр (620): у какой-то строки сменилась стадия — перерисовать
function kfExpireTick(){
  var sig = killfeed.map(kfStage).join("");
  if(sig !== kfExpireTick._s){ kfExpireTick._s = sig; renderFeed(); }
}
function renderFeed(){
  var el = document.getElementById("killfeed"); if(!el) return;
  el.innerHTML = killfeed.filter(function(k){ return kfStage(k) < 2; }).map(function(k){
    var old = kfStage(k) === 1 ? " old" : "";
    if(k.kind === "kill"){
      var W = WEAPONS[k.w], wn = W ? W.name : (k.w === "MOLOTOV" ? "молотов" : k.w === "KNIFE" ? "нож" : k.w === "C4" ? "бомба" : k.w);
      var wkey = k.w === "KNIFE" && k.attTeam === "T" ? "KNIFE_T" : k.w;
      var h = k.att == null ? '' : '<span class="'+k.attTeam.toLowerCase()+'">'+esc(k.att)+'</span>';
      if(k.as) h += (k.asFlash ? kfSvg("flash", "md fl", KF_MOD_T.flash) : '<span class="pl">+</span>')+'<span class="'+k.attTeam.toLowerCase()+' as">'+esc(k.as)+'</span>';
      h += kfSvg(wkey, "wp", wn) || '<span class="w">'+esc(wn)+'</span>';
      ["smoke","wall","hs","noscope","blind"].forEach(function(m){ if(k[m]) h += kfSvg(m, "md", KF_MOD_T[m]); });
      return '<div class="kf'+kfIn(k)+old+(k.tk ? ' tk" title="убил своего' : '')+'">'+h+'<span class="'+k.vicTeam.toLowerCase()+'">'+esc(k.vic)+'</span></div>';
    }
    return '<div class="kf ev '+k.kind+kfIn(k)+old+'">'+esc(k.text)+'</div>';
  }).join("");
}
var bannerTimer = null;
function showBanner(text, team, ms){
  var el = document.getElementById("banner"); if(!el) return;
  var big = /^(ACE|КЛАТЧ)/.test(String(text));
  // (DESIGN.md «Баннер события») «4K — ник», «КЛАТЧ 1v3 — ник!» → плашка события + ник; иначе — одна строка
  var t2 = nickify(text), m2 = /^(\dK|ACE|КЛАТЧ 1v\d) — (.+?)!?$/.exec(t2);
  el.innerHTML = m2 ? '<span class="bn-tag">'+esc(m2[1].replace(/1v(\d)/, "1 на $1"))+'</span><span class="bn-who">'+esc(m2[2])+'</span>' : '<span class="bn-who">'+esc(t2)+'</span>';
  if(/\bshow\b/.test(el.className)){ el.className = ""; void el.offsetWidth; }   // уже показан — раскрыть заново
  el.className = "show "+(team||"").toLowerCase()+(big ? " big" : "");
  if(bannerTimer) clearTimeout(bannerTimer);
  bannerTimer = setTimeout(function(){ el.className = ""; }, ms||2000);
}
// клатч: один игрок против двух и больше — подсвечиваем, пока не решится
function checkClutch(){
  if(roundState !== "live") return;
  ["CT","T"].forEach(function(team){
    var mine = bots.filter(function(b){ return b.team===team && b.alive; });
    var theirs = bots.filter(function(b){ return b.team!==team && b.alive; });
    // Клатч объявляется, только если он ВЫИГРАН (см. showRoundCard); здесь —
    // тихо запоминаем ситуацию: кто остался один и против скольких (максимум)
    if(mine.length === 1 && theirs.length >= 2){
      if(!clutchInfo || clutchInfo.id !== mine[0].id) clutchInfo = {id:mine[0].id, team:team, n:theirs.length};
      else clutchInfo.n = Math.max(clutchInfo.n, theirs.length);
    }
  });
}
var cardTimer = null;
function showRoundCard(winner, reason){
  var el = document.getElementById("roundCard"); if(!el) return;
  var why = {elim:"все противники уничтожены", time:"время вышло", bomb:"бомба взорвалась", defuse:"бомба обезврежена"}[reason] || reason;
  // лучший игрок раунда: фраги, при равенстве — урон
  var mvp = null;
  bots.forEach(function(b){
    if(winner && b.team !== winner) return;
    var sc = (b.roundKills||0)*1000 + (b.roundDmg||0);
    if(reason === "defuse" && bomb && bomb.state === "defused" && b.team === "CT" && b.defuseUntil && Math.abs(b.defuseUntil - tick) < 2) sc += 5000;
    if(!mvp || sc > mvp.sc) mvp = {b:b, sc:sc};
  });
  var clutch = clutchInfo && winner && clutchInfo.team === winner;
  if(clutch){
    clutchShown = clutchInfo.id;
    showBanner("КЛАТЧ 1v"+clutchInfo.n+" — "+clutchInfo.id+"!", winner, 3200);
    logEvent("Клатч выигран: "+clutchInfo.id+" (1v"+clutchInfo.n+")", true);
    feedEvent("clutch", "Клатч 1v"+clutchInfo.n+" — "+clutchInfo.id);
  }
  el.innerHTML = '<div class="rc-bar"></div><div class="rc-in"><div class="rc-t '+(winner||"").toLowerCase()+'">'+(winner ? "Победа "+esc(TEAM_NAME[winner]) : "Ничья")+'</div>'+
    '<div class="rc-r">Раунд '+roundNum+' · '+(winner ? 'за '+winner+' · ' : '')+why+'</div>'+
    (clutch ? '<div class="rc-c">клатч 1v'+clutchInfo.n+' выигран — '+esc(nick(clutchInfo.id))+'</div>' : '')+
    (mvp && mvp.b ? '<div class="rc-m"><div class="rc-ph">'+plPhoto(mvp.b)+'</div><div class="rc-mv">MVP <b>'+esc(nick(mvp.b.id))+'</b>'+(ROLE_LABEL[mvp.b.tRole] ? ' · '+ROLE_LABEL[mvp.b.tRole] : '')+'<br>'+(mvp.b.roundKills||0)+' фраг(а), '+Math.round(mvp.b.roundDmg||0)+' урона</div></div>' : '')+
    '<div class="rc-s"><span class="ct">'+esc(TEAM_NAME.CT)+'</span> '+score.CT+'<i>:</i>'+score.T+' <span class="t">'+esc(TEAM_NAME.T)+'</span></div><div class="rc-h" id="rcHalf"></div></div><div class="rc-next" title="до следующего раунда"><b id="rcNext"></b></div>';
  el.className = ""; void el.offsetWidth;   // (v430) показ заново — анимации с начала
  el.className = "show "+(winner||"").toLowerCase();
  // (DESIGN.md «Карточка конца раунда») карточка живёт, пока раунд в «ending» (640: scoreboardUpdate снимает её с концом состояния игры);
  // был таймер реального времени — при ускоренной игре / перемотке карточка висела на закупке следующего раунда
  if(cardTimer){ clearTimeout(cardTimer); cardTimer = null; }
}

// (v275) панель экономики сворачивается: клик по заголовку; выбор помнится в этом браузере
var econClosed = false; try { econClosed = localStorage.getItem("econClosed") === "1"; } catch(e){}
(function(){ var el = document.getElementById("econ"); if(!el) return;
  el.addEventListener("pointerdown", function(e){ if(e.button !== 0 || !(e.target.closest && e.target.closest(".ec-tg"))) return;
    econClosed = !econClosed; try { localStorage.setItem("econClosed", econClosed ? "1" : "0"); } catch(e2){} renderEcon(); });
  el.addEventListener("keydown", function(e){ if((e.key === "Enter" || e.key === " ") && e.target.closest && e.target.closest(".ec-tg")){ e.preventDefault();
    econClosed = !econClosed; try { localStorage.setItem("econClosed", econClosed ? "1" : "0"); } catch(e2){} renderEcon(); el.querySelector(".ec-tg").focus(); } });
})();
function renderEcon(){
  var el = document.getElementById("econ"); if(!el) return;
  var h = '<button type="button" class="ec-tg" aria-expanded="'+(!econClosed)+'" title="'+(econClosed ? 'Показать экономику' : 'Скрыть экономику')+'"><span class="ec-ar"></span>Экономика<span class="ec-rn">раунд '+roundNum+(roundNum>HALF_ROUNDS?' · 2-я половина':'')+'</span></button>';
  el.classList.toggle("closed", econClosed);
  if(econClosed){ domHtml(el, h); return; }
  ["CT","T"].forEach(function(team){
    var te = teamEco[team];
    var mates = bots.filter(function(b){ return b.team===team; });
    var total = mates.reduce(function(a,b){ return a+b.money; }, 0);
    var tl = team.toLowerCase();
    h += '<div class="tm '+tl+'"><span class="tm-n"><i>'+team+'</i>'+ROUND_TYPE_LABEL[te.roundType]+'</span><span class="tm-m">$'+total+'<small> · при поражении +'+LOSS_BONUS[Math.min(4,te.lossLevel)]+'</small></span></div>';
    if(team === "T" && teamTac.T){ var PH = {setup:"сетап", execute:"выход", postplant:"пост-плант"}; var RC = (teamTac.T.recalls || []).map(function(r){ return ' → <b>перекол '+r.from+' → '+r.to+'</b> ('+r.sec+' с)'; }).join('');   // (v450) переколы раунда
      h += '<div class="ec-i t">тактика «'+teamTac.T.tac.name+'» · <b>'+PH[teamTac.T.phase]+'</b>'+RC+'</div>';
      if(teamTac.T.read) h += '<div class="ec-i t sub">IGL: '+teamTac.T.read+'</div>'; }
    if(team === "CT" && teamTac.CT && teamTac.CT.setup){ h += '<div class="ec-i ct sub">расстановка «'+teamTac.CT.setup.name+'»'+(teamTac.CT.setupWhy ? ' — '+teamTac.CT.setupWhy : '')+'</div>'; }
    if(team === "CT"){ var cl = teamTac.CT && teamTac.CT.call; h += '<div class="ec-i ct">'+(bomb && bomb.state==="planted" ? (cl0save() ? "сейв" : (bomb.retake ? (bomb.retake.phase==="gather" ? (bomb.retake.need === 1 && aliveCount("CT") <= 1 ? "ретейк "+bomb.site+" в одиночку: подход" : "ретейк "+bomb.site+": сбор "+(bomb.retake.ready||0)+"/"+(bomb.retake.need||"?")) : bomb.retake.phase==="util" ? "ретейк "+bomb.site+": флешка — сейчас заход" : "ретейк "+bomb.site+": заход!") : "ретейк "+bomb.site)) : (cl ? "колл: T на "+cl.site+" (~"+Math.max(1,Math.round(cl.count))+") — ротируют "+Object.keys(teamTac.CT.rot||{}).length : "расстановка по ролям"))+'</div>'; }
    h += '<table>';
    mates.forEach(function(b){
      var wpn = WEAPONS[b.primary || b.secondary].name;
      var arm = (b.helmet ? "КШ" : (b.armor ? "К" : "—")) + (b.armor && b.armorHp != null && b.armorHp < 100 ? " "+b.armorHp : "") + (b.kit ? "+кит" : "");
      var c4 = bomb && bomb.carrier === b ? hudC4("c4i") : "";
      var nd = b.nades ? ('<i class="nd s"></i>'.repeat(b.nades.smoke) + '<i class="nd f"></i>'.repeat(b.nades.flash) + '<i class="nd h"></i>'.repeat(b.nades.he) + '<i class="nd m"></i>'.repeat(b.nades.molly)) : "";
      h += '<tr class="'+(b.alive?'':'dead')+'"><td class="nm" title="'+esc(b.prof ? b.prof.style+" · aim "+b.prof.aim+", агрессия "+b.prof.aggr+", дисциплина "+b.prof.disc+(b._mistakes ? " · ошибок: "+b._mistakes : "") : "")+'"><span class="pn">'+pnum(b.id)+'</span>'+esc(nick(b.id))+c4+'</td><td class="rl">'+(ROLE_LABEL[b.tRole]||"")+(b.retakeRole && bomb && bomb.state==="planted" && !cl0save() ? ' · '+({defuser:"дефузер",cover:"прикрытие",flank:"фланг"}[b.retakeRole]) : "")+'</td><td class="wp">'+wpn+'</td><td class="ar">'+arm+'</td><td class="ndc" title="серый — дым · белый — флешка · красный — HE · оранжевый — молотов">'+nd+'</td><td class="kd">'+b.kills+'/'+b.deaths+'</td><td class="m">$'+b.money+'</td></tr>';
    });
    h += '</table>';
  });
  domHtml(el, h);
}

